import { createRequire } from "node:module"
import { resolve } from "node:path"
import {
  ApiExtraModels,
  ApiOkResponse,
  ApiResponse,
  DocumentBuilder,
  getSchemaPath,
  SwaggerModule,
} from "@nestjs/swagger"
import { cleanupOpenApiDoc } from "nestjs-zod"
import { z } from "zod"

const contractPath = resolve(process.cwd(), "dist/openapi-contracts.json")
const require = createRequire(contractPath)
const { apiSuccessSchema, apiErrorSchema } = require("./common/api/schema.js")

export function createOpenApiDocument(app) {
  // Generated by the compiler plugin to map each route to its DTO and errors.
  const contract = require(contractPath)

  applyRouteContracts(contract)

  const swaggerConfig = new DocumentBuilder()
    .setTitle("Trading API")
    .setVersion("1.0")
    .setOpenAPIVersion("3.2.0")
    .build()

  const document = SwaggerModule.createDocument(app, swaggerConfig)

  return cleanupOpenApiDoc(document, { version: "3.1" })
}

function applyRouteContracts(contract) {
  for (const route of contract.routes) {
    const controller = require(route.controllerModule)[route.controller]
    const successDto = require(route.success.module)[route.success.exportName]
    const descriptor = Object.getOwnPropertyDescriptor(
      controller.prototype,
      route.method
    )

    // Bind the route DTO to the shared success response policy.
    const successResponse = z.toJSONSchema(apiSuccessSchema)
    delete successResponse.$schema
    successResponse.properties.data = route.success.isArray
      ? { type: "array", items: { $ref: getSchemaPath(successDto) } }
      : { $ref: getSchemaPath(successDto) }

    // Register the DTO referenced by getSchemaPath in components.schemas.
    ApiExtraModels(successDto)(controller.prototype, route.method, descriptor)
    ApiOkResponse({
      schema: successResponse,
    })(controller.prototype, route.method, descriptor)

    const errorsByStatus = new Map()

    for (const error of route.errors) {
      const factory = require(error.module)[error.exportName][error.key]
      const errors = errorsByStatus.get(factory.status) ?? []

      errors.push(factory)
      errorsByStatus.set(factory.status, errors)
    }

    for (const [status, errors] of errorsByStatus) {
      ApiResponse({
        status,
        description: errors.map((error) => error.description).join("\n"),
        content: {
          "application/json": {
            schema: {
              oneOf: errors.map((error) => {
                // Bind each declared error to the shared failure response policy.
                const errorResponse = z.toJSONSchema(apiErrorSchema)
                delete errorResponse.$schema

                const properties = errorResponse.properties.error.properties
                const data = z.toJSONSchema(error.dataSchema)
                delete data.$schema

                properties.type.enum = [error.type]
                properties.type.example = error.type
                properties.status.enum = [error.status]
                properties.status.example = error.status
                properties.message.example = error.message
                properties.data = data

                return errorResponse
              }),
            },
          },
        },
      })(controller.prototype, route.method, descriptor)
    }
  }
}
